function factorial(n: number): number {
    if (n <= 1) return 1
    return n * factorial(n - 1)
}

function sumDigits(n: number): number {
    if (n < 10) return n
    return (n % 10) + sumDigits(Math.floor(n / 10))
}

console.log("5! =", factorial(5))
console.log("10! =", factorial(10))
