function discount(price: number, percent: number): number {
    if (price <= 0) return 0
    if (percent <= 0) return price
    if (percent >= 100) return 0
    return price * (1 - percent / 100)
}
console.log(discount(100, 20), discount(100, 0), discount(100, 150), discount(-5, 10))

function power(base: number, exp: number): number {
    if (exp === 0) return 1
    const half = power(base, Math.floor(exp / 2))
    return exp % 2 === 0 ? half * half : half * half * base
}
console.log(power(2, 10), power(3, 5), power(5, 0))

type Nested = number | Nested[]
function flatten(arr: Nested[]): number[] {
    const out: number[] = []
    for (const x of arr) Array.isArray(x) ? out.push(...flatten(x)) : out.push(x)
    return out
}
