function align(text: string, dir: "left" | "right" | "center" = "left", width = 12) {
    if (dir === "right") return text.padStart(width, ".")
    if (dir === "center") return text.padStart((width + text.length) >> 1, ".").padEnd(width, ".")
    return text.padEnd(width, ".")
}
