function createBankAccount(initialBalance: number) {
    let balance = initialBalance
    const history: string[] = []

    return {
        deposit(amount: number): void {
            balance += amount
            history.push(`+${amount}`)
        },
        withdraw(amount: number): boolean {
            if (amount > balance) return false
            balance -= amount
            history.push(`-${amount}`)
            return true
        },
        getBalance: () => balance,
        getHistory: () => [...history],
    }
}

