type Events = { login: { user: string }; logout: undefined }
class Emitter {
    private handlers = new Map<keyof Events, Array<(p: never) => void>>()
    on<K extends keyof Events>(e: K, fn: (p: Events[K]) => void) {
        this.handlers.set(e, [...(this.handlers.get(e) ?? []), fn])
    }
    emit<K extends keyof Events>(e: K, p: Events[K]) {
        for (const fn of this.handlers.get(e) ?? []) (fn as (p: Events[K]) => void)(p)
    }
}
