type Task<T> = () => Promise<T>
async function runAll<T>(tasks: Task<T>[]): Promise<T[]> {
    const results: T[] = []
    for (const t of tasks) results.push(await t())
    return results
}
console.log(await runAll([async () => 1, async () => 2, () => Promise.resolve(3)]))

async function pool<T>(tasks: (() => Promise<T>)[], limit: number): Promise<T[]> {
    const results: T[] = new Array(tasks.length)
    let next = 0
    const worker = async () => { while (next < tasks.length) { const i = next++; results[i] = await tasks[i]() } }
    await Promise.all(Array.from({ length: limit }, worker))
    return results
}
const delay = (v: number) => () => new Promise<number>(r => setTimeout(() => r(v), 10 - v))
