function* take<T>(src: Iterable<T>, n: number) {
    if (n <= 0) return
    for (const x of src) { yield x; if (--n === 0) return }
}
function* naturals() { let i = 1; while (true) yield i++ }
console.log([...take(naturals(), 7)])

function* map<T, U>(src: Iterable<T>, fn: (x: T) => U) { for (const x of src) yield fn(x) }
function* filter<T>(src: Iterable<T>, p: (x: T) => boolean) { for (const x of src) if (p(x)) yield x }
function* nat() { let i = 1; while (true) yield i++ }
function* first<T>(src: Iterable<T>, n: number) { for (const x of src) { if (n-- <= 0) return; yield x } }
console.log([...first(map(filter(nat(), n => n % 7 === 0), n => n * n), 4)])

type TreeNode = { name: string; children?: TreeNode[] }
function* walk(node: TreeNode, depth = 0): Generator<string> {
    yield "  ".repeat(depth) + node.name
    for (const c of node.children ?? []) yield* walk(c, depth + 1)
}
const tree: TreeNode = { name: "src", children: [{ name: "app", children: [{ name: "main.ts" }] }, { name: "utils.ts" }] }
for (const line of walk(tree)) console.log(line)

function* chunk<T>(arr: T[], size: number) {
    for (let i = 0; i < arr.length; i += size) yield arr.slice(i, i + size)
}
