function* zip<A, B>(a: Iterable<A>, b: Iterable<B>): Generator<[A, B]> {
    const ia = a[Symbol.iterator](), ib = b[Symbol.iterator]()
    while (true) {
        const x = ia.next(), y = ib.next()
        if (x.done || y.done) return
        yield [x.value, y.value]
    }
}
console.log([...zip(["a", "b", "c"], [1, 2, 3, 4])])

function* enumerate<T>(src: Iterable<T>, start = 0): Generator<[number, T]> {
    let i = start
    for (const x of src) yield [i++, x]
}
